{"query":"query UserStats($name: String) {
  User(name: $name) {
    id
    name
    avatar { medium }
    bannerImage
    statistics {
      anime {
        count meanScore minutesWatched episodesWatched
        scores { score count }
        statuses { status count }
        formats { format count }
        genres { genre count meanScore }
        releaseYears { releaseYear count }
        startYears { startYear count }
      }
      manga {
        count meanScore chaptersRead volumesRead
        scores { score count }
        statuses { status count }
        formats { format count }
        genres { genre count meanScore }
        releaseYears { releaseYear count }
        startYears { startYear count }
      }
    }
  }
}","variables":{"name":"Neartana"}}

{"query":"query UserTitles($name: String, $type: MediaType, $chunk: Int!) {
  MediaListCollection(userName: $name, type: $type, chunk: $chunk, perChunk: 500) {
    hasNextChunk
    lists {
      entries {
        progress
        status
        score(format: POINT_100)
        media {
          id
          title { romaji english native }
          coverImage { large }
          format
          episodes
          duration
          chapters
          genres
          startDate { year }
        }
      }
    }
  }
}","variables":{"name":"Neartana","type":"ANIME","chunk":1}}

